	c, ok, err := usableCurrentLogin()
	if err != nil {
		return "", err
	}
	if !ok {
		return "", nil
	}
	return strings.Join([]string{
		"login",
		strings.TrimRight(c.CoreURL, "/"),
		c.Handle,
		c.KeychainService,
	}, "|"), nil
